input.command:
cd /tmp && gbrain setup claude-code --json > /tmp/gbrain-setup.json 2>/tmp/gbrain-setup.err; echo exit=$?; cat /tmp/gbrain-setup.err | tail -60; python3 -I -c "
import json;d=json.load(open('/tmp/gbrain-setup.json'))
print('verify:',json.dumps(d.get('verify'),indent=1)[:1500]); print('state:',d.get('state'))
for n in d.get('notices',[]): print(n.get('code'), n.get('kind')); print(n.get('user_message'))
"

node -e "
const d=require('/tmp/gbrain-setup.json');
console.log('state:',d.state); console.log('verify:',JSON.stringify(d.verify,null,1).slice(0,1500));
console.log('instructions:',d.instructions&&d.instructions.action,d.instructions&&d.instructions.detail);
for(const n of d.notices||[]){console.log('---',n.code,n.kind);console.log(n.user_message);if(n.decisions)for(const x of n.decisions)console.log(' *',x.id,'default=',x.default)}
"; cat /harness-state/claude/CLAUDE.md

mkdir -p /tmp/gb-scripts && cat > /tmp/gb-scripts/mcp.js <<'EOF'
const {spawn}=require('child_process');
const p=spawn('/harness-state/.gbrain/hook-launcher/gbrain-hook',['/harness-state/.bun/bin/gbrain','serve','--surface','starter','--advertise','verbs'],{cwd:'/tmp'});
let buf='';const pend={};let id=0;
p.stdout.on('data',d=>{buf+=d;let i;while((i=buf.indexOf('\n'))>=0){const l=buf.slice(0,i);buf=buf.slice(i+1);try{const m=JSON.parse(l);if(m.id&&pend[m.id]){pend[m.id](m);delete pend[m.id]}}catch{}}});
const rpc=(method,params)=>new Promise(r=>{const i=++id;pend[i]=r;p.stdin.write(JSON.stringify({jsonrpc:'2.0',id:i,method,params})+'\n')});
(async()=>{
 await rpc('initialize',{protocolVersion:'2025-06-18',capabilities:{},clientInfo:{name:'install-check',version:'1'}});
 p.stdin.write(JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'})+'\n');
 const t=await rpc('tools/list',{});console.log('tools:',t.result.tools.map(x=>x.name).join(', '));
 const r=await rpc('tools/call',{name:'recall',arguments:{entity:'gbrain-install-check'}});
 const txt=r.result?.content?.map(c=>c.text).join('')||JSON.stringify(r);
 console.log('recall via MCP:',(txt.match(/"fact":\s*"[^"]+"/)||[txt.slice(0,500)])[0]);
 p.kill();
})();
EOF
node /tmp/gb-scripts/mcp.js
